class Task:
    def __init__(self, C, D, T):
        self.C = C  # WCET
        self.D = D  # Relative Deadline
        self.T = T  # Period

def compute_total_utilization(task_set):
    U_tau = 0
    for task_i in task_set:
        U_tau += task_i.C / task_i.T
    return U_tau

def evaluate_empirical_schedulability(scheduler, task_set_generator, m, target_X_percent):
    schedulable_count = 0
    total_count = 0
    for task_set in task_set_generator.generate_task_sets():
        U_tau = compute_total_utilization(task_set)
        if U_tau / m <= target_X_percent / 100:
            total_count += 1
            if scheduler.can_schedule(task_set, m):
                schedulable_count += 1
    return (schedulable_count / total_count) * 100 if total_count > 0 else 0

def create_transformed_reservation(task, k_i):
    if not is_implicit_deadline(task):
        raise ValueError("Task must be implicit-deadline")
    if not isinstance(k_i, int) or k_i <= 0:
        raise ValueError("k_i must be a positive integer")

    Q_i = task.C / k_i
    delta_i = task.T / k_i
    return PollingReservation(task.C, task.T, Q=Q_i, delta=delta_i)
